CREATE SCHEMA IF NOT EXISTS fleet_q8; SET search_path TO fleet_q8,public;
CREATE TABLE IF NOT EXISTS vehicles(vehicle_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,registration TEXT UNIQUE NOT NULL,current_odometer NUMERIC(12,2) NOT NULL CHECK(current_odometer>=0),last_service_odometer NUMERIC(12,2) NOT NULL CHECK(last_service_odometer>=0 AND last_service_odometer<=current_odometer));
CREATE TABLE IF NOT EXISTS trips(trip_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,vehicle_id INT NOT NULL REFERENCES vehicles,trip_on DATE NOT NULL,start_odometer NUMERIC(12,2) NOT NULL,end_odometer NUMERIC(12,2) NOT NULL,CHECK(end_odometer>start_odometer));
CREATE TABLE IF NOT EXISTS service_alerts(vehicle_id INT PRIMARY KEY REFERENCES vehicles,km_since_service NUMERIC(12,2) NOT NULL,flagged_on DATE NOT NULL);
INSERT INTO vehicles VALUES(1,'ABC001',12000,8000),(2,'ABC002',8000,4000),(3,'ABC003',5000,4500) ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION fn_service_due(p_vehicle_id INT) RETURNS BOOLEAN LANGUAGE plpgsql AS $$
DECLARE c NUMERIC; s NUMERIC; BEGIN SELECT current_odometer,last_service_odometer INTO c,s FROM vehicles WHERE vehicle_id=p_vehicle_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown vehicle'; END IF; RETURN c-s>=5000; END $$;
CREATE OR REPLACE FUNCTION fn_trip_odometer_update() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c NUMERIC; BEGIN SELECT current_odometer INTO c FROM vehicles WHERE vehicle_id=NEW.vehicle_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown vehicle'; END IF; IF NEW.start_odometer<>c THEN RAISE EXCEPTION 'Trip must start at current odometer %',c; END IF; IF NEW.end_odometer<=NEW.start_odometer THEN RAISE EXCEPTION 'End odometer must exceed start'; END IF; UPDATE vehicles SET current_odometer=NEW.end_odometer WHERE vehicle_id=NEW.vehicle_id; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_trip_odometer_update ON trips;
CREATE TRIGGER trg_trip_odometer_update BEFORE INSERT ON trips FOR EACH ROW EXECUTE FUNCTION fn_trip_odometer_update();
CREATE OR REPLACE PROCEDURE pr_record_trip(p_vehicle_id INT,p_trip_on DATE,p_start NUMERIC,p_end NUMERIC) LANGUAGE plpgsql AS $$
BEGIN IF NOT EXISTS(SELECT 1 FROM vehicles WHERE vehicle_id=p_vehicle_id) THEN RAISE EXCEPTION 'Unknown vehicle'; END IF; IF p_trip_on IS NULL OR p_start IS NULL OR p_end IS NULL OR p_end<=p_start THEN RAISE EXCEPTION 'Invalid trip details'; END IF; INSERT INTO trips(vehicle_id,trip_on,start_odometer,end_odometer) VALUES(p_vehicle_id,p_trip_on,p_start,p_end); END $$;
-- Six trips inserted through the procedure; each starts at the vehicle's current odometer.
CALL pr_record_trip(1,CURRENT_DATE-5,12000,12200); CALL pr_record_trip(1,CURRENT_DATE-4,12200,12500);
CALL pr_record_trip(2,CURRENT_DATE-5,8000,8100); CALL pr_record_trip(2,CURRENT_DATE-4,8100,8300);
CALL pr_record_trip(3,CURRENT_DATE-5,5000,5200); CALL pr_record_trip(3,CURRENT_DATE-4,5200,5500);
CREATE OR REPLACE VIEW v_service_due AS SELECT registration,current_odometer-last_service_odometer AS km_since_service FROM vehicles WHERE current_odometer-last_service_odometer>=5000;
CREATE INDEX IF NOT EXISTS ix_trips_vehicle_trip_on ON trips(vehicle_id,trip_on);
EXPLAIN SELECT * FROM trips WHERE vehicle_id=1 AND trip_on BETWEEN CURRENT_DATE-30 AND CURRENT_DATE;
CREATE OR REPLACE PROCEDURE pr_refresh_service_alerts() LANGUAGE plpgsql AS $$
BEGIN INSERT INTO service_alerts(vehicle_id,km_since_service,flagged_on) SELECT vehicle_id,current_odometer-last_service_odometer,CURRENT_DATE FROM vehicles WHERE current_odometer-last_service_odometer>=5000 ON CONFLICT(vehicle_id) DO UPDATE SET km_since_service=EXCLUDED.km_since_service,flagged_on=EXCLUDED.flagged_on; DELETE FROM service_alerts a USING vehicles v WHERE a.vehicle_id=v.vehicle_id AND v.current_odometer-v.last_service_odometer<5000; END $$;
CALL pr_refresh_service_alerts();
-- Schedule every Monday at 06:00: CALL fleet_q8.pr_refresh_service_alerts().
SELECT * FROM v_service_due; SELECT * FROM service_alerts;